// Generate tests/fixtures/hull-white.sexp from QuantLib's HullWhite model:
// discount bonds and discount bond options, European swaptions
// (JamshidianSwaptionEngine, TreeSwaptionEngine), Bermudan swaptions
// (TreeSwaptionEngine) and a callable bond (TreeCallableFixedRateBondEngine).
//
//   nix develop .#fixtures -c sh tests/fixtures/generate.sh
//
// Valued on 2026-09-24. The model is fitted to the EURIBOR 6M curve of
// fixture_curves.hpp, which also forecasts the swaps' floating legs: Hull-White
// pricing is single-curve. Exercise dates fall on the swaps' reset dates, so
// QuantLib's DiscretizedSwaption snaps nothing.

#include "fixture_curves.hpp"

#include <ql/experimental/callablebonds/callablebond.hpp>
#include <ql/experimental/callablebonds/treecallablebondengine.hpp>
#include <ql/version.hpp>

#include <cstdio>
#include <string>
#include <vector>

using namespace QuantLib;
using fixture::iso;
using fixture::parseDate;
using fixture::today;

namespace {

ext::shared_ptr<VanillaSwap> swapFrom(bool payer, double nominal, double rate, const Date& start,
                                      const Date& end, const ext::shared_ptr<IborIndex>& index) {
    Schedule fixed(start, end, 1 * Years, TARGET(), ModifiedFollowing, ModifiedFollowing,
                   DateGeneration::Backward, false);
    Schedule floating(start, end, 6 * Months, TARGET(), ModifiedFollowing, ModifiedFollowing,
                      DateGeneration::Backward, false);
    return ext::make_shared<VanillaSwap>(payer ? Swap::Payer : Swap::Receiver, nominal, fixed, rate,
                                         Thirty360(Thirty360::BondBasis), floating, index, 0.0,
                                         Actual360());
}

}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::fprintf(stderr, "usage: %s output.sexp\n", argv[0]);
        return 1;
    }
    Settings::instance().evaluationDate() = today;
    FILE* out = std::fopen(argv[1], "w");
    std::fprintf(out, ";;;; hull-white.sexp --- generated by tests/fixtures/generate.sh from QuantLib %s\n",
                 QL_VERSION);
    fixture::Curves curves = fixture::buildCurves();
    Handle<YieldTermStructure> curve = curves.euriborHandle;
    auto euribor = ext::make_shared<Euribor6M>(curve);
    DayCounter dc = curve->dayCounter();

    struct Params { double a, sigma; };
    std::vector<Params> params = {{0.05, 0.01}, {0.15, 0.008}, {1e-10, 0.006}};
    std::vector<Date> resets = {Date(28, September, 2027), Date(28, September, 2028),
                                Date(28, September, 2029), Date(30, September, 2030),
                                Date(29, September, 2031)};
    Date end(28, September, 2036);   // unadjusted: the schedules fall on the exercise dates

    std::fprintf(out, "(:models\n (\n");
    for (const Params& p : params) {
        auto model = ext::make_shared<HullWhite>(curve, p.a, p.sigma);
        std::fprintf(out, "  (:a %.17g :sigma %.17g\n", p.a, p.sigma);

        // Analytic discount bonds and options.
        std::fprintf(out, "   :discounts (");
        for (double t : {0.5, 1.0, 2.0, 5.0, 10.0, 20.0})
            std::fprintf(out, "(%.17g %.17g) ", t, model->discount(t));
        std::fprintf(out, ")\n   :bonds (");
        for (double t : {0.5, 2.0, 5.0})
            for (double T : {t + 0.25, t + 3.0})
                for (double r : {-0.01, 0.02, 0.06})
                    std::fprintf(out, "(%.17g %.17g %.17g %.17g) ", t, T, r,
                                 model->discountBond(t, T, r));
        std::fprintf(out, ")\n   :bond-options (");
        for (double t : {0.5, 2.0, 5.0})
            for (double T : {t + 1.0, t + 4.0})
                for (double k : {0.9, 1.0})
                    for (int put = 0; put < 2; ++put)
                        std::fprintf(out, "(%s %.17g %.17g %.17g %.17g %.17g) ", put ? ":put" : ":call",
                                     k, t, t + 0.01, T,
                                     model->discountBondOption(put ? Option::Put : Option::Call, k, t,
                                                               t + 0.01, T));
        std::fprintf(out, ")\n");

        // Co-terminal European swaptions: Jamshidian and the tree.
        auto jamshidian = ext::make_shared<JamshidianSwaptionEngine>(model);
        std::fprintf(out, "   :europeans (");
        for (const Date& reset : resets) {
            for (int payer = 0; payer < 2; ++payer) {
                auto swap = swapFrom(payer, 1e6, 0.027, reset, end, euribor);
                Swaption swaption(swap, ext::make_shared<EuropeanExercise>(reset));
                swaption.setPricingEngine(jamshidian);
                Real analytic = swaption.NPV();
                swaption.setPricingEngine(ext::make_shared<TreeSwaptionEngine>(model, 200));
                std::fprintf(out, "(\"%s\" %s %.17g %.17g) ", iso(reset).c_str(),
                             payer ? ":payer" : ":receiver", analytic, swaption.NPV());
            }
        }
        std::fprintf(out, ")\n");

        // Bermudans exercisable on every reset date, on several grids.
        std::fprintf(out, "   :bermudans (");
        for (int payer = 0; payer < 2; ++payer) {
            for (double rate : {0.022, 0.027, 0.032}) {
                auto swap = swapFrom(payer, 1e6, rate, resets.front(), end, euribor);
                Swaption swaption(swap, ext::make_shared<BermudanExercise>(resets));
                for (Size steps : {50, 200}) {
                    swaption.setPricingEngine(ext::make_shared<TreeSwaptionEngine>(model, steps));
                    std::fprintf(out, "(%s %.17g %d %.17g) ", payer ? ":payer" : ":receiver", rate,
                                 int(steps), swaption.NPV());
                }
            }
        }
        std::fprintf(out, ")\n");

        // A callable bond: 10Y annual 3%, callable at par (clean) on its coupon
        // dates from the third.
        Schedule schedule(Date(28, September, 2026), Date(28, September, 2036), 1 * Years, TARGET(),
                          Unadjusted, Unadjusted, DateGeneration::Backward, false);
        CallabilitySchedule calls;
        for (Size i = 3; i < schedule.size() - 1; ++i)
            calls.push_back(ext::make_shared<Callability>(Bond::Price(100.0, Bond::Price::Clean),
                                                          Callability::Call, schedule[i]));
        CallableFixedRateBond callable(2, 100.0, schedule, {0.03}, Thirty360(Thirty360::BondBasis),
                                       Following, 100.0, Date(), calls);
        std::fprintf(out, "   :callable (");
        for (Size steps : {40, 200}) {
            callable.setPricingEngine(ext::make_shared<TreeCallableFixedRateBondEngine>(model, steps));
            std::fprintf(out, "(%d %.17g %.17g) ", int(steps), callable.NPV(), callable.cleanPrice());
        }
        std::fprintf(out, "))\n");
    }
    std::fprintf(out, " ))\n");
    std::fclose(out);
    return 0;
}
